    "clientIp.v.okBody": "如果這就是你的網路在網際網路上的位址，登入與連線紀錄都是對的。",
    "clientIp.v.hopsTooLowTitle": "代理比 Telepy 算的多一層",
    "clientIp.v.hopsTooHighTitle": "Telepy 算的代理比實際多",
    "clientIp.v.hopsBody": "在 {where} 把「信任的代理層數」設成 {setting}，再檢查一次。改成 {auto} 則是把每一段內部位址都當成代理，層數就不必對。",
    "clientIp.v.useHeaderTitle": "{header} 標頭裡有你的公網位址",
    "clientIp.v.useHeaderBody": "在 {where} 把「訪客位址標頭」設成 {setting}——但只有在 Telepy 前面的代理一定會自己設定這個標頭時才行，不然訪客可以自己寫。",
    "clientIp.v.headerPrivateTitle": "訪客位址標頭給的是內部位址",
    "clientIp.v.headerPrivateBody": "{header} 帶的是 {ip}。檢查設定它的代理，或在 {where} 清掉「訪客位址標頭」。",
    "clientIp.v.allPrivateTitle": "傳到 Telepy 的每一段都是內部位址",
    "clientIp.v.allPrivateBody": "Telepy 前面的代理在轉送請求時就已經弄丟你的位址了（{ip} 是它自己網路裡的位址）。Telepy 這邊怎麼設都找不回來，要修的是那個代理。",
    "clientIp.v.directBody": "這個請求沒有任何代理加上 X-Forwarded-For：它直接從 {ip} 連到 Telepy，你在 Telepy 自己的機器或網路裡瀏覽時就是這樣。外面的訪客會經過代理，請從外部網路再檢查一次。",
    "clientIp.v.unknownTitle": "Telepy 判斷不出這個請求從哪裡來",
    "clientIp.v.unknownBody": "後端沒收到 X-Forwarded-For，也拿不到連線的來源位址。",
    "clientIp.fix.title": "怎麼修 Telepy 前面的代理",
    "clientIp.fix.hostNet": "跑在 Docker 裡、透過發佈 port 收連線的反向代理（例如 Nginx Proxy Manager）常常把每個訪客都看成 Docker bridge。改用 {mode} 或不放在 Docker 裡跑，它才看得到真實位址。",
    "clientIp.fix.ipv6": "訪客走 IPv6、容器網路卻只有 IPv4 時，Docker 的 userland proxy 會改寫來源：替那個網路開 IPv6，或在 Docker 的 daemon.json 設 {setting}。",
    "clientIp.fix.noCdn": "Telepy 沒收到 {header} 之類的 CDN 標頭，所以這個請求沒經過 Cloudflare 或其他 CDN。Cloudflare 的 DNS 記錄設成「僅限 DNS」（灰色雲朵）時，訪客會直接連到你的代理。這時不要設 {setting}：那個標頭訪客可以自己帶。",
    "clientIp.fix.after": "然後回來這裡再檢查一次。「信任的代理層數」設成 {setting} 會自己跳過每一層內網的代理；填數字則是後端前面固定那麼多層（含 Traefik）（{where}）。",
    "clientIp.fix.outside": "從你自己的網路以外檢查，例如用手機的行動網路：在家裡連自己的公網位址再繞回來時，路由器的 NAT loopback 可能把來源換成它自己的內部位址。",
    "clientIp.shortChain": "這個請求經過的代理比「信任的代理層數」（{setting}）少。如果你的環境本來就是這樣，請在 {where} 調低它；不然從這條路連進來的訪客可以自己決定被記成什麼位址。",
    "clientIp.headerAbsent": "「訪客位址標頭」設成 {header}，但這個請求沒帶它，所以 Telepy 改用 X-Forwarded-For。",
    "clientIp.probe.button": "拿假位址試試看",
    "clientIp.probe.hint": "帶著假的 X-Forwarded-For 與 X-Real-IP 標頭再檢查一次。訪客不應該能自己決定 Telepy 記下什麼位址。",
    "clientIp.probe.safe": "安全：Telepy 沒採用假位址。",
    "clientIp.probe.spoofableTitle": "訪客可以自己決定 Telepy 記下的位址",
    "clientIp.probe.realIp": "Telepy 記下了假的 {ip}：Telepy 前面的代理信任訪客自己送來的 X-Real-IP 標頭（nginx 的 real_ip，Nginx Proxy Manager 預設就這樣設），把它當成來源轉送過來。讓那個代理只信任你自己的代理送的 X-Real-IP（{setting}），或在那裡關掉 real_ip。",
    "clientIp.probe.sameCause": "原因和上面一樣：每個訪客到了那個代理都變成內部位址（{ip}），而 Nginx Proxy Manager 預設信任內部位址送來的 X-Real-IP。代理看得到真實位址之後，這個問題也會一起消失。",
    "clientIp.probe.forwardedFor": "Telepy 從 X-Forwarded-For 記下了假的 {ip}：「信任的代理層數」（{setting}）算的代理比這個請求實際經過的多，請在 {where} 調低。",
    "clientIp.hopsAuto": "自動：每一段內部位址都算代理（這個請求跳過了 {n} 段）",
    "clientIp.hopsFixed": "固定層數，含 Traefik",
    "clientIp.v.hopsBodyAuto": "自動計算時，前面一台公網 IP 的代理被當成訪客了。在 {where} 把「信任的代理層數」設成 {setting}（後端前面的代理層數，含 Traefik），再檢查一次。",
    "clientIp.probe.autoInternalTitle": "內網的訪客能自己選要被記成什麼位址",
    "clientIp.probe.autoInternal": "Telepy 記下了假的 {ip}：你現在是從內部位址瀏覽，而「信任的代理層數」設成 {setting} 會把每一段內部位址都當成代理，所以越過了你的位址。網際網路上的訪客做不到這件事；內網的人也只能改自己的紀錄。要完全排除，在 {where} 把「信任的代理層數」設成後端前面的代理層數。",
