    // 為什麼 / Why
    "wizard.why.title": "為什麼要這一步？",
    "wizard.why.device": "是裝置主動連出到 Telepy，而不是反過來，所以它不需要公開 IP，也不用開任何埠。Telepy 只放行它認得金鑰的裝置。",
    "wizard.why.devicePoint1": "你的內網本來就把裝置隔離得很好：外面的裝置連不進來。Telepy 不會破壞這點：不開任何埠，裝置只發出一條對外的連線。",
    "wizard.why.devicePoint2": "這把金鑰只能開這一條通道，就算外洩也碰不到你的其他裝置。",
    "wizard.why.devicePoint3": "按下繼續時，Telepy 會替這台裝置保留一個專屬埠。",
    "wizard.why.accounts": "Telepy 會以真實的系統帳號登入裝置。所有與你共用這條通道的人都用同一把 Telepy 金鑰進來，所以這份清單就是限制能用哪些帳號的關卡。",
    "wizard.why.accountsPoint1": "請填裝置上真的存在的帳號。不確定的話，在裝置上執行 whoami。",
    "wizard.why.accountsPoint2": "共用對象只能使用你之後分配給他們的帳號。",
    "wizard.why.accountsPoint3": "之後隨時可以從通道選單修改這份清單。",
    "wizard.why.authorize": "網頁終端機、檔案管理和遠端瀏覽器，都是透過通道登入裝置自己的 sshd。sshd 只接受列在 authorized_keys 裡的金鑰。",
    "wizard.why.authorizePoint1": "Telepy 服務金鑰負責網頁終端機、檔案、遠端瀏覽器與 AI 工作階段。",
    "wizard.why.authorizePoint2": "你自己的金鑰讓你能從筆電直接 ssh 進去。如果選了「裝上我的金鑰」，這一步之後 Telepy 會幫你加上。",
    "wizard.why.authorizePoint3": "指令只會附加，不會覆蓋：原有的金鑰都會保留，重跑也不會重複加入。",
    "wizard.why.connect": "裝置主動連到 Telepy 並維持這條連線，這條對外連線就是通道，所以在 NAT 或防火牆後面也能用。",
    "wizard.why.connectPoint1": "快速測試會在你關閉執行它的終端機時中斷。",
    "wizard.why.connectPoint2": "AutoSSH、systemd 服務和 Docker 都會自動重連，長期使用請選其中一種。",
    "wizard.why.connectPoint3": "裝置一連上狀態就會變綠，不需要重新整理。",
    "wizard.why.verify": "Telepy 現在會透過通道，以每個帳號實際登入一次，走的就是網頁終端機的路徑，讓問題現在就浮現，而不是之後才發現。",
    "wizard.why.verifyPoint1": "登入被拒，幾乎都是因為金鑰不在該帳號的 authorized_keys 裡。",
    "wizard.why.verifyPoint2": "顯示離線？確認步驟 4 的指令還在裝置上執行。",
    "wizard.why.verifyPoint3": "修好了嗎？重新檢查就好，不必重建任何東西。",
