    "wizard.connect.transportAutoHint": "建議用這個。先走 SSH 的 port；被擋時（防火牆，或網頁的名稱在只轉網頁 port 的代理後面），通道每次重連都會自己改從網頁的 port 進來。腳本會為此下載一個小的 python3 程式；裝置沒有 python3 就只走 SSH 的 port。",
