    "sheet.ref.exec": "執行單一指令",
    "sheet.tip.lowPorts": "你電腦上 1024 以下的埠需要管理員權限，請用 8080 而不是 80。",
    "sheet.tip.inUse": "出現「Address already in use」表示那個埠已經有程式在用，換一個本機埠即可。",
    "sheet.tip.windows": "Windows 10/11 內建同一套 OpenSSH 用戶端，在 PowerShell 或 Windows Terminal 執行即可（背景執行的用 Stop-Process -Name ssh 停止）。",
    "sheet.tip.deviceKey": "裝置上的目標使用者也要信任你的公鑰（放在它的 ~/.ssh/authorized_keys）。「第一次使用的設定」第 3 步可以幫你放進去。",
    "sheet.tip.forwarding": "裝置的 sshd 必須允許轉發（AllowTcpForwarding，預設開啟）。",
    "sheet.tip.gatewayPorts": "-R 只在裝置的 localhost 監聽；要讓其他機器連進來，裝置的 sshd 需要開 GatewayPorts。",
    "sheet.emptyTitle": "還沒有通道",
    "sheet.emptyBody": "請先建立一條通道，指令速查會自動帶入它的名稱、埠與伺服器。",
    "sheet.explain.ssh": "OpenSSH 用戶端，macOS、Linux 與 Windows 10 以上都內建。",
    "sheet.explain.noShell": "不在裝置上開 shell，只做轉發。",
    "sheet.explain.background": "連上後轉到背景，關掉終端機也會繼續執行。",
    "sheet.explain.keepAlive": "每 30 秒送一次 keep-alive，閒置的轉發才不會被斷掉。",
    "sheet.explain.exitOnFailure": "埠開不起來就立刻結束，而不是少了它還繼續跑。",
    "sheet.explain.localForward": "在你電腦的 {localPort} 埠監聽，把每條連線送到「從裝置看出去的」{host}:{remotePort}。",
    "sheet.explain.dynamicForward": "在你電腦的 {port} 埠開 SOCKS5 代理，流量從裝置出去。",
    "sheet.explain.remoteForward": "在裝置的 {devicePort} 埠監聽，把每條連線送回你電腦的 localhost:{localPort}。",
    "sheet.explain.alias": "你 ~/.ssh/config 裡的 {alias}：經 Telepy 的伺服器區塊，以 {user} 登入。",
    "sheet.explain.jumpServer": "先經過 Telepy 伺服器，取代 ~/.ssh/config 的設定。",
    "sheet.explain.directTarget": "這條通道在 Telepy 伺服器上的埠（{port}），以 {user} 登入裝置。",
    "sheet.explain.jumpDevice": "經過 {alias} 跳到下一台機器。",
    "sheet.explain.jumpChain": "先經過 Telepy 伺服器，再經過裝置（以 {user}），跳到下一台機器。",
    "sheet.explain.lanPort": "那台機器的 SSH 埠（{port}）。",
    "sheet.explain.lanTarget": "以 {user} 登入 {host}，也就是裝置網路裡的那台機器。",
    "sheet.explain.scp": "走 SSH 的安全複製；-r 連資料夾一起複製。",
    "sheet.explain.scpPort": "這條通道在 Telepy 伺服器上的埠（{port}），scp 要用大寫 -P。",
    "sheet.explain.rsync": "rsync：保存模式（-a）、詳細輸出（-v）、壓縮（-z）、顯示進度，只傳有變動的部分。",
    "sheet.explain.rsyncShell": "告訴 rsync 怎麼連到裝置：經 Telepy 伺服器到這條通道的埠（{port}）。",
    "sheet.explain.copyFromLocal": "從你的電腦複製 {path}。",
    "sheet.explain.copyToLocal": "放到你電腦上的 {path}。",
    "sheet.explain.copyToDevice": "放到裝置上的 {path}。",
    "sheet.explain.copyFromDevice": "從裝置複製 {path}。",
    "sheet.explain.copyToLanHost": "放到 {host} 的 {path}。",
    "sheet.explain.copyFromLanHost": "從 {host} 複製 {path}。",
    "sheet.explain.remoteCommand": "要在裝置上執行的指令，輸出會傳回這裡。",

