    "join.why.title": "為什麼用一行指令？",
    "join.why.body": "它在裝置上一次做完逐步設定的所有事（金鑰、授權、服務、檢查），不用來回複製貼上。",
    "join.why.point1": "指令只能用一次、30 分鐘後失效，而且只能把裝置加到你的帳號。",
    "join.why.point2": "腳本只會在 authorized_keys 追加一行，並核對 Telepy 的主機金鑰；可以先用「查看腳本內容」看過再執行。",
    "join.why.point3": "裝置只會主動連到 Telepy，不會開任何對外的連入埠。",
