    "join.howDownload": "先下載、檢查、再執行",
    "join.howDownloadHint": "路由器或序列埠主控台貼上時可能掉字：先把檔案下載下來，用 sh -n 檢查語法，腳本動手前也會核對自己的校驗碼。把腳本內文貼進終端機執行不在支援範圍。",
    "join.wgetLabel": "沒有 curl 時（原廠 OpenWrt 有 wget）：",
    "join.checkTitle": "先測試，不消耗指令",
    "join.checkBody": "--check 會做到註冊之前的每一步，不用 token：說出找到哪個 shell、HTTP 工具、SSH client（OpenSSH 或 Dropbear）與服務管理器，用嚴格握手核對這台機器的 SSH 伺服器與主機金鑰，並確認連得到 Telepy 的 gateway（包括這個版本的 SSH keepalive 是否正常）。",
    "join.flow.s1": "看裝置有什麼：shell、HTTP 工具、SSH client（OpenSSH 或 dbclient）、服務管理器",
    "join.flow.s2": "讀取 SSH 伺服器的主機金鑰，並以嚴格握手核對",
    "join.flow.s3": "確認 Telepy 的 gateway 有回應、釘住它的主機金鑰、測試 keepalive",
