    "siteSettings.terminal_detach_max_secs.description": "瀏覽器斷線（換網路、筆電睡著、重新整理）後，網頁終端機的 shell 最多等同一個人回來這麼久。每個人在偏好設定選自己的時間（預設是斷線就結束），實際用兩者較短的那個；通道也可以設成一律立刻結束。設 0 = 關閉這個功能。最多 86400。",
