    "siteSettings.signin_lifetime.label": "維持登入",
    "siteSettings.signin_lifetime.description": "沒有任何造訪時，登入可以維持多久。每次造訪都會延長（分頁開著時瀏覽器會在背景自動續期），所以常用的人不會被登出；超過這段時間沒來才需要重新登入。登出則立刻結束。5 分鐘到 365 天。",
    "siteSettings.signin_access_lifetime.label": "Access token 效期",
    "siteSettings.signin_access_lifetime.description": "每顆短效 access token 的有效時間；到期前瀏覽器會用登入工作階段自動換一顆新的，使用者不會察覺。越短，外洩的 token 能用的時間越短。1 分鐘到 24 小時。",
