    "siteSettings.signin_consent_style.description": "/oauth/authorize，已登入的人在這裡允許 MCP 應用程式或 telepy login。兩種樣子都會列出應用程式、導回哪裡、權限與通道；低調樣子拿掉連線示意圖與步驟。telepy login 登入完成後顯示的那一頁也跟著這個樣子。",
