    "about.disclaimer": "使用聲明",
    "about.disclaimerDescription": "連接裝置或授權任何程式之前，請先讀過以下內容。",
    "about.disclaimerLicence": "授權條款（AGPL-3.0）",
    "about.disclaimer.asIsTitle": "依現狀提供，不附任何擔保",
    "about.disclaimer.asIsBody": "Telepy 是以 AGPL-3.0 授權的自由軟體，依「現狀」提供，不附任何明示或默示的擔保，包括可銷售性、特定用途適用性及不侵權。在法律允許的範圍內，作者與貢獻者對因使用或無法使用 Telepy 所生的任何損害，包括資料遺失、服務中斷、系統遭入侵或財務損失，均不負責（AGPL-3.0 第 15、16 條）。",
    "about.disclaimer.machinesTitle": "你操作的是真實的機器",
    "about.disclaimer.machinesBody": "終端機、檔案管理、遠端桌面、遠端瀏覽器、工具箱指令片段與 SSH 轉發，都直接作用在你的裝置及其網路中的機器上。刪除、覆寫、關機、修改權限或防火牆，多半無法復原。動手前請確認自己在哪台機器、用哪個帳號，並自行備份重要資料。指令規則、身分確認（step-up）與錄影是用來減少失誤，不是安全邊界，也攔不下所有危險操作。",
    "about.disclaimer.authorizedTitle": "只連接你有權使用的系統",
    "about.disclaimer.authorizedBody": "只把你擁有、或已取得明確授權的裝置與網路接上 Telepy。對未經授權的系統進行網路掃描、跳板連線或轉發連接埠，可能觸犯法律（例如中華民國刑法第三十六章「妨害電腦使用罪」），也可能違反你所屬組織的規定。相關責任由使用者自行承擔，與 Telepy 及其作者無關。",
    "about.disclaimer.credentialsTitle": "金鑰、Token 與登入授權，跟密碼一樣重要",
    "about.disclaimer.credentialsBody": "你的 SSH 金鑰、API Token（tpt_…）、CLI 登入與 MCP 應用程式的連線，都能以你的權限連到你的裝置，它們做的事都算在你名下。請像保管密碼一樣保管：不要貼到聊天室、程式碼庫或公開的 CI 記錄；每一個都只給需要的範圍、通道與期限；用不到的立即撤銷。",
    "about.disclaimer.agentsTitle": "MCP 代理會照它讀到的內容行動",
    "about.disclaimer.agentsBody": "你連接的 MCP 應用程式，可以在你核准的範圍內於裝置上執行指令、讀寫檔案、操作瀏覽器。AI 可能誤解你的意思、產生錯誤的指令，或被網頁、檔案、指令輸出裡暗藏的指示誘導（提示注入，prompt injection），去做你沒要求的事。請只連接你信任的應用程式、給最小的範圍與通道、為高風險指令設定需要核准的規則，並到「AI 活動」頁檢查它做了什麼。代理用你給的權限做的事，由你負責。",
    "about.disclaimer.sharingTitle": "分享就是把鑰匙交出去",
    "about.disclaimer.sharingBody": "分享通道、給予 ADMIN 權限或開放某個登入帳號，對方就能以那個帳號在裝置上操作。只分享給你信任的人，能設結束時間就設，並定期檢查誰有權限。",
    "about.disclaimer.operatorsTitle": "如果你是這台 Telepy 的管理員",
    "about.disclaimer.operatorsBody": "自行架設 Telepy 的管理員，須自行負責伺服器的安全（SECRET_KEY、TLS、更新、備份）、所發出的帳號與權限，並遵守適用的個人資料保護法規（例如《個人資料保護法》）。Telepy 會保存 IP 位址、登入紀錄、稽核日誌，以及開啟錄影之通道的終端機輸出；請告知使用者會記錄哪些內容、保存多久。",
    "about.disclaimer.closing": "使用 Telepy 即表示你了解上述風險，並對自己的使用方式負責。本聲明是授權條款之外的補充，並不變更授權條款。",
