    "health.check.audit_log.title": "審計紀錄完整性",
    "health.check.audit_log.what": "逐筆驗證閘道事件、登入紀錄與代理程式活動的雜湊鏈，任何一筆被改或被刪都會看得出來。",
    "health.check.audit_log.fix": "鏈斷了代表有資料在 Telepy 之外被改過，例如直接編輯資料庫。{mismatch} 或 {missing} 表示 {file} 記得的鏈和這個資料庫對不上，通常是因為資料庫從備份還原過或被換掉（例如從另一台伺服器搬過來）。知道原因之後請按「重新封存」：每一列現在的樣子成為新的基準，誰做的、為什麼都留在日誌與 {file} 裡。「確認」則只是讓這個結果先不算警報。如果沒人說得出原因，請當成可能遭到竄改：拿你另外保存的 {file} 比對，並查清楚誰有存取權。若顯示「cannot verify」，問題則在資料庫本身。",
