    "siteSettings.client_ip_hops.label": "信任的代理層數",
    "siteSettings.client_ip_hops.description": "X-Forwarded-For 裡哪些是代理：自動（右邊的內部位址都跳過，第一個公網位址是訪客），或後端前面固定的代理層數（含 Traefik）。結果可以在管理區 → 伺服器狀態檢查。下一個請求就生效。",
