    "siteSettings.server_keep_shared_service_key.label": "在裝置上保留共用服務金鑰",
    "siteSettings.server_keep_shared_service_key.description": "即使裝置上每條通道都有自己的金鑰，也不移除共用的 web-service 金鑰。之前的 Telepy 伺服器還在用這把金鑰登入同一批裝置時打開。",
    "siteSettings.server_gateway_proxy_protocol_from.label": "SSH 閘道的 PROXY protocol 來源",
